Extensions.ExtractScript:
# Writes each embedded file below to disk during specialize. Encoding per extension:
# UTF-8 with BOM for .ps1/.xml and UTF-16LE with BOM for .reg/.vbs/.js. Inner text is
# trimmed, so CDATA bodies start without indentation. Content comes only from this file.
param(
    [xml] $Document
);

$scriptsDir = 'C:\ProgramData\Autounattend\Unattend\Scripts\';
foreach( $file in $Document.unattend.Extensions.File ) {
    $path = [System.Environment]::ExpandEnvironmentVariables(
        $file.GetAttribute( 'path' )
    );
    if( $path.StartsWith( $scriptsDir ) ) {
        mkdir -Path $scriptsDir -ErrorAction 'SilentlyContinue';
    }
    $encoding = switch( [System.IO.Path]::GetExtension( $path ) ) {
        { $_ -in '.ps1', '.xml' } { [System.Text.Encoding]::UTF8; }
        { $_ -in '.reg', '.vbs', '.js' } { [System.Text.UnicodeEncoding]::new( $false, $true ); }
        default { [System.Text.Encoding]::Default; }
    };
    [System.IO.File]::WriteAllBytes( $path, ( $encoding.GetPreamble() + $encoding.GetBytes( $file.InnerText.Trim() ) ) );
}

Extensions.File:
#Requires -Version 5.1
<#
.SYNOPSIS
    Temporarily disables network adapters during OOBE and restores only the
    adapters that TMPC disabled, after OOBE has completed.
.DESCRIPTION
    The previous administrative state is persisted in a machine registry key
    before any adapter is changed. Adapters are identified by InterfaceGuid and
    the restore plan never enables an adapter that was not disabled by TMPC.
    A recovery task is registered only when the first restore attempt leaves
    present adapters disabled; it runs at logon, requires OOBE to be complete,
    is bounded and unregisters itself after success. No AtStartup task and no
    indiscriminate enable-all path is used.
.NOTES
    Windows PowerShell 5.1. No downloads, no reboots, no personal data.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('Disable', 'Restore', 'Recover')]
    [string]$Mode
)

$ErrorActionPreference = 'Stop'
$script:StateKey = 'HKLM:\SOFTWARE\TMPC-Windows-11-Optimization\NetworkRestore'
$script:RecoveryDir = 'C:\ProgramData\TMPC-Windows-11-Optimization'
$script:RecoveryScript = 'C:\ProgramData\TMPC-Windows-11-Optimization\NetworkGuard.ps1'
$script:RecoveryTaskName = 'TMPCNetworkRestoreRecovery'
$script:RecoveryTaskPath = '\TMPC\'
$script:MaxRecoveryAttempts = 5
$script:LogPath = 'C:\ProgramData\TMPC-Windows-11-Optimization\Logs\NetworkGuard.log'

function Write-NetworkLog {
    param([string]$Message, [ValidateSet('INFO', 'SUCCESS', 'WARNING', 'ERROR')][string]$Level = 'INFO')
    try {
        $directory = Split-Path -Parent $script:LogPath
        if (-not (Test-Path -LiteralPath $directory)) { New-Item -Path $directory -ItemType Directory -Force -ErrorAction Stop | Out-Null }
        $line = '[{0}] [{1}] {2}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Level, $Message
        Add-Content -LiteralPath $script:LogPath -Value $line -Encoding UTF8 -ErrorAction Stop
    } catch { }
}

function Test-TMPCPrivilegedSid {
    param([string]$Sid)
    if ([string]::IsNullOrWhiteSpace($Sid)) { return $false }
    if ($Sid -in @('S-1-5-18', 'S-1-5-32-544', 'S-1-3-0', 'S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464')) { return $true }
    if ($Sid -match '^S-1-5-21-\d+-\d+-\d+-(512|519)$') { return $true }
    return $false
}

function Get-TMPCNetworkStateAclSnapshot {
    param([string]$Path)
    $acl = Get-Acl -LiteralPath $Path -ErrorAction Stop
    $ownerSid = [string]$acl.Owner
    try { $ownerSid = ([System.Security.Principal.NTAccount]::new([string]$acl.Owner)).Translate([System.Security.Principal.SecurityIdentifier]).Value } catch { }
    $rules = @()
    foreach ($rule in @($acl.Access)) {
        $identity = [string]$rule.IdentityReference
        try { $identity = $rule.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]).Value } catch { }
        $rules += [pscustomobject]@{
            Identity = [string]$identity
            Rights   = [int]$rule.RegistryRights
            Type     = [string]$rule.AccessControlType
        }
    }
    return [pscustomobject]@{ OwnerSid = [string]$ownerSid; Rules = @($rules) }
}

function Test-TMPCNetworkStateAclSnapshot {
    param($Snapshot)
    if ($null -eq $Snapshot) { return $false }
    if (-not (Test-TMPCPrivilegedSid -Sid ([string]$Snapshot.OwnerSid))) { return $false }
    $unsafe = [int]([System.Security.AccessControl.RegistryRights]::SetValue -bor
        [System.Security.AccessControl.RegistryRights]::CreateSubKey -bor
        [System.Security.AccessControl.RegistryRights]::Delete -bor
        [System.Security.AccessControl.RegistryRights]::ChangePermissions -bor
        [System.Security.AccessControl.RegistryRights]::TakeOwnership)
    foreach ($rule in @($Snapshot.Rules)) {
        if ([string]$rule.Type -ne 'Allow') { continue }
        if (Test-TMPCPrivilegedSid -Sid ([string]$rule.Identity)) { continue }
        if (([int]$rule.Rights -band $unsafe) -ne 0) { return $false }
    }
    return $true
}

# File-system ACL controls for the recovery script. They mirror the summary
# controls in SystemCustomizations.ps1: effective Allow rules are evaluated with
# numeric FileSystemRights masks, the owner must be privileged and reparse
# points are rejected. Ancestors may grant the standard create-folder right;
# the recovery directory and script must not grant any non-privileged write,
# append, delete, permission or ownership change.
function Get-TMPCNetworkFileAclSnapshot {
    param([string]$Path)
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    $acl = Get-Acl -LiteralPath $Path -ErrorAction Stop
    $ownerSid = [string]$acl.Owner
    try { $ownerSid = ([System.Security.Principal.NTAccount]::new([string]$acl.Owner)).Translate([System.Security.Principal.SecurityIdentifier]).Value } catch { }
    $rules = @()
    foreach ($rule in @($acl.Access)) {
        $identity = [string]$rule.IdentityReference
        try { $identity = $rule.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]).Value } catch { }
        $rules += [pscustomobject]@{
            Identity  = [string]$identity
            Rights    = [int]$rule.FileSystemRights
            Type      = [string]$rule.AccessControlType
            Inherited = [bool]$rule.IsInherited
        }
    }
    return [pscustomobject]@{
        Path        = [string]$item.FullName
        Exists      = $true
        IsContainer = [bool]$item.PSIsContainer
        IsReparse   = (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)
        OwnerSid    = [string]$ownerSid
        Rules       = @($rules)
    }
}

function Test-TMPCNetworkPathAclSnapshot {
    param($Snapshot, [ValidateSet('Ancestor', 'Directory', 'File')][string]$Kind)
    if ($null -eq $Snapshot -or -not $Snapshot.Exists) { return $false }
    if ([bool]$Snapshot.IsReparse) { return $false }
    if ($Kind -eq 'Directory' -and -not [bool]$Snapshot.IsContainer) { return $false }
    if ($Kind -eq 'File' -and [bool]$Snapshot.IsContainer) { return $false }
    if (-not (Test-TMPCPrivilegedSid -Sid ([string]$Snapshot.OwnerSid))) { return $false }
    $rights = [System.Security.AccessControl.FileSystemRights]
    $unsafe = switch ($Kind) {
        'Ancestor' {
            [int]($rights::Delete -bor $rights::DeleteSubdirectoriesAndFiles -bor
                $rights::ChangePermissions -bor $rights::TakeOwnership -bor
                $rights::WriteData -bor $rights::WriteAttributes -bor
                $rights::WriteExtendedAttributes)
        }
        'Directory' {
            [int]($rights::Delete -bor $rights::DeleteSubdirectoriesAndFiles -bor
                $rights::ChangePermissions -bor $rights::TakeOwnership -bor
                $rights::WriteData -bor $rights::AppendData -bor
                $rights::WriteAttributes -bor $rights::WriteExtendedAttributes)
        }
        default {
            [int]($rights::WriteData -bor $rights::AppendData -bor
                $rights::WriteAttributes -bor $rights::WriteExtendedAttributes -bor
                $rights::Delete -bor $rights::ChangePermissions -bor $rights::TakeOwnership)
        }
    }
    foreach ($rule in @($Snapshot.Rules)) {
        if ([string]$rule.Type -ne 'Allow') { continue }
        if (Test-TMPCPrivilegedSid -Sid ([string]$rule.Identity)) { continue }
        if (@($rule.PSObject.Properties.Name) -notcontains 'Rights') { return $false }
        if (([int]$rule.Rights -band $unsafe) -ne 0) { return $false }
    }
    return $true
}

function Test-TMPCNetworkRecoveryLocationDecision {
    param(
        [object[]]$AncestorSnapshots,
        $DirectorySnapshot,
        $SourceDirectorySnapshot,
        $SourceSnapshot,
        $TargetSnapshot
    )
    foreach ($snapshot in @($AncestorSnapshots)) {
        if (-not (Test-TMPCNetworkPathAclSnapshot -Snapshot $snapshot -Kind 'Ancestor')) {
            return [pscustomobject]@{ Safe = $false; Reason = 'ANCESTOR_ACL_UNTRUSTED' }
        }
    }
    if (-not (Test-TMPCNetworkPathAclSnapshot -Snapshot $DirectorySnapshot -Kind 'Directory')) {
        return [pscustomobject]@{ Safe = $false; Reason = 'DESTINATION_DIRECTORY_UNTRUSTED' }
    }
    if (-not (Test-TMPCNetworkPathAclSnapshot -Snapshot $SourceDirectorySnapshot -Kind 'Directory')) {
        return [pscustomobject]@{ Safe = $false; Reason = 'SOURCE_DIRECTORY_UNTRUSTED' }
    }
    if (-not (Test-TMPCNetworkPathAclSnapshot -Snapshot $SourceSnapshot -Kind 'File')) {
        return [pscustomobject]@{ Safe = $false; Reason = 'SOURCE_SCRIPT_UNTRUSTED' }
    }
    if ($null -ne $TargetSnapshot -and -not (Test-TMPCNetworkPathAclSnapshot -Snapshot $TargetSnapshot -Kind 'File')) {
        return [pscustomobject]@{ Safe = $false; Reason = 'DESTINATION_SCRIPT_UNTRUSTED' }
    }
    return [pscustomobject]@{ Safe = $true; Reason = 'TRUSTED' }
}

function Test-TMPCNetworkRecoveryLocation {
    param([string]$SourcePath, [string]$RecoveryDirectory, [string]$RecoveryScript)
    try {
        if (-not (Test-Path -LiteralPath $SourcePath -PathType Leaf)) {
            return [pscustomobject]@{ Safe = $false; Reason = 'SOURCE_SCRIPT_MISSING' }
        }
        if (-not (Test-Path -LiteralPath $RecoveryDirectory -PathType Container)) {
            return [pscustomobject]@{ Safe = $false; Reason = 'DESTINATION_DIRECTORY_MISSING' }
        }
        $components = @()
        $current = $RecoveryDirectory
        while ($current) {
            $components = @($current) + $components
            $parent = Split-Path -Parent $current
            if (-not $parent -or [string]::Equals($parent, $current, [StringComparison]::OrdinalIgnoreCase)) { break }
            $current = $parent
        }
        $ancestors = @()
        for ($i = 0; $i -lt $components.Count; $i++) {
            $snapshot = Get-TMPCNetworkFileAclSnapshot -Path $components[$i]
            if ($i -eq ($components.Count - 1)) { $directorySnapshot = $snapshot }
            else { $ancestors += $snapshot }
        }
        $sourceDirectorySnapshot = Get-TMPCNetworkFileAclSnapshot -Path (Split-Path -Parent $SourcePath)
        $sourceSnapshot = Get-TMPCNetworkFileAclSnapshot -Path $SourcePath
        $targetSnapshot = $null
        if (Test-Path -LiteralPath $RecoveryScript) { $targetSnapshot = Get-TMPCNetworkFileAclSnapshot -Path $RecoveryScript }
        return Test-TMPCNetworkRecoveryLocationDecision -AncestorSnapshots @($ancestors) -DirectorySnapshot $directorySnapshot -SourceDirectorySnapshot $sourceDirectorySnapshot -SourceSnapshot $sourceSnapshot -TargetSnapshot $targetSnapshot
    } catch {
        return [pscustomobject]@{ Safe = $false; Reason = 'SECURITY_CHECK_FAILED' }
    }
}

function Test-TMPCNetworkOobeComplete {
    try {
        $state = (Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Setup\State' -Name 'ImageState' -ErrorAction Stop).ImageState
        return ([string]$state -eq 'IMAGE_STATE_COMPLETE')
    } catch { return $false }
}

function Test-TMPCNetworkStateSchema {
    param($State)
    if ($null -eq $State) { return $false }
    foreach ($name in @('SchemaVersion', 'RequestId', 'Phase', 'CreatedUtc', 'UpdatedUtc', 'Adapters')) {
        if (@($State.PSObject.Properties.Name) -notcontains $name) { return $false }
    }
    if ([int]$State.SchemaVersion -ne 1) { return $false }
    $requestGuid = [Guid]::Empty
    if (-not [Guid]::TryParse([string]$State.RequestId, [ref]$requestGuid) -or $requestGuid -eq [Guid]::Empty) { return $false }
    if ([string]$State.Phase -notin @('PENDING_DISABLE', 'DISABLED', 'PARTIAL_DISABLE', 'RESTORE_PENDING', 'RESTORED', 'RESTORED_WITH_ABSENT')) { return $false }
    $created = [DateTime]::MinValue
    if (-not [DateTime]::TryParse([string]$State.CreatedUtc, [ref]$created)) { return $false }
    foreach ($entry in @($State.Adapters)) {
        if ($null -eq $entry) { return $false }
        foreach ($name in @('InterfaceGuid', 'Description', 'PreviousStatus', 'DisableAttempted', 'DisabledByTmpc', 'RestoreStatus')) {
            if (@($entry.PSObject.Properties.Name) -notcontains $name) { return $false }
        }
        $adapterGuid = [Guid]::Empty
        if (-not [Guid]::TryParse([string]$entry.InterfaceGuid, [ref]$adapterGuid) -or $adapterGuid -eq [Guid]::Empty) { return $false }
        if ($entry.DisableAttempted -isnot [bool] -or $entry.DisabledByTmpc -isnot [bool]) { return $false }
        if ([string]$entry.RestoreStatus -notin @('PENDING', 'NOT_APPLIED', 'NOT_DISABLED', 'RESTORED_VERIFIED', 'ALREADY_ENABLED', 'ABSENT_NOT_RESTORED', 'RESTORE_FAILED')) { return $false }
    }
    return $true
}

function Get-TMPCNetworkAdapterGuid {
    param($Adapter)
    if ($null -eq $Adapter) { return $null }
    $guid = [Guid]::Empty
    if (-not [Guid]::TryParse([string]$Adapter.InterfaceGuid, [ref]$guid) -or $guid -eq [Guid]::Empty) { return $null }
    return $guid.ToString()
}

function Get-TMPCNetworkDisablePlan {
    param([object[]]$Adapters)
    $selected = @()
    $skipped = @()
    foreach ($adapter in @($Adapters)) {
        $guid = Get-TMPCNetworkAdapterGuid -Adapter $adapter
        if (-not $guid) { $skipped += [pscustomobject]@{ InterfaceGuid = $null; Reason = 'INVALID_GUID' }; continue }
        $status = [string]$adapter.Status
        if ($status -eq 'Disabled') { $skipped += [pscustomobject]@{ InterfaceGuid = $guid; Reason = 'ALREADY_DISABLED' }; continue }
        if ($status -eq 'Not Present') { $skipped += [pscustomobject]@{ InterfaceGuid = $guid; Reason = 'NOT_PRESENT' }; continue }
        $selected += [pscustomobject]@{
            InterfaceGuid   = $guid
            Description       = [string]$adapter.InterfaceDescription
            PreviousStatus    = $status
            DisableAttempted  = $false
            DisabledByTmpc    = $false
            RestoreStatus     = 'PENDING'
        }
    }
    return [pscustomobject]@{ Selected = @($selected); Skipped = @($skipped) }
}

function Get-TMPCNetworkRestorePlan {
    param([object[]]$PersistedAdapters, [object[]]$CurrentAdapters, [bool]$OobeComplete)
    if (-not $OobeComplete) {
        return [pscustomobject]@{ Decision = 'DEFER'; Reason = 'OOBE_NOT_COMPLETE'; Actions = @() }
    }
    $actions = @()
    foreach ($entry in @($PersistedAdapters)) {
        if ($null -eq $entry) { continue }
        $eligible = ($entry.DisabledByTmpc -eq $true) -or ($entry.DisableAttempted -eq $true)
        if (-not $eligible) { continue }
        $guid = Get-TMPCNetworkAdapterGuid -Adapter $entry
        if (-not $guid) { $actions += [pscustomobject]@{ Action = 'INVALID'; InterfaceGuid = $null; Reason = 'INVALID_GUID' }; continue }
        $current = @($CurrentAdapters | Where-Object { $_ -and [string]::Equals((Get-TMPCNetworkAdapterGuid -Adapter $_), $guid, [StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
        if ($current.Count -eq 0) {
            $actions += [pscustomobject]@{ Action = 'ABSENT'; InterfaceGuid = $guid; Reason = 'ADAPTER_NOT_PRESENT' }
            continue
        }
        $status = [string]$current[0].Status
        if ($status -eq 'Disabled') {
            $actions += [pscustomobject]@{ Action = 'ENABLE'; InterfaceGuid = $guid; Reason = 'DISABLED_BY_TMPC' }
        } elseif ($status -eq 'Not Present') {
            $actions += [pscustomobject]@{ Action = 'ABSENT'; InterfaceGuid = $guid; Reason = 'ADAPTER_NOT_PRESENT' }
        } else {
            $actions += [pscustomobject]@{ Action = 'ALREADY_ENABLED'; InterfaceGuid = $guid; Reason = 'STATE_PRESERVED' }
        }
    }
    if ($actions.Count -eq 0) { return [pscustomobject]@{ Decision = 'NO_ACTION'; Reason = 'NOTHING_TO_RESTORE'; Actions = @() } }
    return [pscustomobject]@{ Decision = 'RESTORE'; Reason = 'TMPC_ADAPTERS_PENDING'; Actions = @($actions) }
}

function Read-TMPCNetworkState {
    if (-not (Test-Path -LiteralPath $script:StateKey)) { return $null }
    $acl = $null
    try { $acl = Get-TMPCNetworkStateAclSnapshot -Path $script:StateKey } catch { throw 'STATE_ACL_UNREADABLE' }
    if (-not (Test-TMPCNetworkStateAclSnapshot -Snapshot $acl)) { throw 'STATE_ACL_UNTRUSTED' }
    $json = $null
    try { $json = [string](Get-ItemProperty -LiteralPath $script:StateKey -Name 'State' -ErrorAction Stop).State } catch { throw 'STATE_READ_FAILED' }
    try { $state = $json | ConvertFrom-Json } catch { throw 'STATE_INVALID' }
    if (-not (Test-TMPCNetworkStateSchema -State $state)) { throw 'STATE_INVALID' }
    return $state
}

function Write-TMPCNetworkState {
    param($State)
    if (-not (Test-TMPCNetworkStateSchema -State $State)) { throw 'STATE_INVALID' }
    $State.UpdatedUtc = (Get-Date).ToUniversalTime().ToString('o')
    $json = $State | ConvertTo-Json -Depth 8 -Compress
    if (-not (Test-Path -LiteralPath $script:StateKey)) {
        New-Item -Path $script:StateKey -Force -ErrorAction Stop | Out-Null
    }
    $acl = Get-TMPCNetworkStateAclSnapshot -Path $script:StateKey
    if (-not (Test-TMPCNetworkStateAclSnapshot -Snapshot $acl)) { throw 'STATE_ACL_UNTRUSTED' }
    Set-ItemProperty -LiteralPath $script:StateKey -Name 'State' -Type String -Value $json -Force -ErrorAction Stop
    $persisted = [string](Get-ItemProperty -LiteralPath $script:StateKey -Name 'State' -ErrorAction Stop).State
    if (-not [string]::Equals($persisted, $json, [StringComparison]::Ordinal)) { throw 'STATE_VERIFY_FAILED' }
    $parsed = $null
    try { $parsed = $persisted | ConvertFrom-Json } catch { throw 'STATE_VERIFY_FAILED' }
    if (-not (Test-TMPCNetworkStateSchema -State $parsed)) { throw 'STATE_VERIFY_FAILED' }
}

function Get-TMPCNetworkAdapterByGuid {
    param([string]$InterfaceGuid)
    try {
        $match = @(Get-NetAdapter -InterfaceGuid $InterfaceGuid -ErrorAction Stop)
        if ($match.Count -eq 0) { return $null }
        return $match[0]
    } catch { return $null }
}

function Update-TMPCNetworkEntry {
    param($State, [string]$InterfaceGuid, [string]$RestoreStatus, [string]$ErrorCode)
    foreach ($entry in @($State.Adapters)) {
        if ([string]::Equals([string]$entry.InterfaceGuid, $InterfaceGuid, [StringComparison]::OrdinalIgnoreCase)) {
            $entry.RestoreStatus = $RestoreStatus
            if ($ErrorCode) { $entry | Add-Member -NotePropertyName 'Error' -NotePropertyValue $ErrorCode -Force }
            return
        }
    }
}

function Invoke-TMPCNetworkDisable {
    $adapters = @(Get-NetAdapter -ErrorAction Stop)
    $plan = Get-TMPCNetworkDisablePlan -Adapters $adapters
    $state = [pscustomobject]@{
        SchemaVersion = 1
        RequestId     = [Guid]::NewGuid().ToString('D')
        Phase         = 'PENDING_DISABLE'
        CreatedUtc    = (Get-Date).ToUniversalTime().ToString('o')
        UpdatedUtc    = (Get-Date).ToUniversalTime().ToString('o')
        Adapters      = @($plan.Selected)
    }
    try {
        Write-TMPCNetworkState -State $state
    } catch {
        Write-NetworkLog ("Network state could not be persisted before disabling ($($_.Exception.Message)); no adapter was changed.") 'ERROR'
        return 0
    }
    Write-NetworkLog ("Network disable plan: {0} adapter(s) selected, {1} preserved." -f @($plan.Selected).Count, @($plan.Skipped).Count) 'INFO'
    foreach ($entry in @($state.Adapters)) {
        $adapter = Get-TMPCNetworkAdapterByGuid -InterfaceGuid $entry.InterfaceGuid
        if ($null -eq $adapter) {
            Update-TMPCNetworkEntry -State $state -InterfaceGuid $entry.InterfaceGuid -RestoreStatus 'NOT_APPLIED' -ErrorCode 'ADAPTER_NOT_FOUND'
        } elseif ([string]$adapter.Status -eq 'Disabled') {
            Update-TMPCNetworkEntry -State $state -InterfaceGuid $entry.InterfaceGuid -RestoreStatus 'NOT_DISABLED'
        } else {
            $entry.DisableAttempted = $true
            try { Write-TMPCNetworkState -State $state } catch { Write-NetworkLog 'Network state could not be persisted before a disable attempt.' 'ERROR' }
            try {
                Disable-NetAdapter -InputObject $adapter -Confirm:$false -ErrorAction Stop
                $after = Get-TMPCNetworkAdapterByGuid -InterfaceGuid $entry.InterfaceGuid
                if ($null -ne $after -and [string]$after.Status -eq 'Disabled') {
                    $entry.DisabledByTmpc = $true
                    Update-TMPCNetworkEntry -State $state -InterfaceGuid $entry.InterfaceGuid -RestoreStatus 'PENDING'
                } else {
                    Update-TMPCNetworkEntry -State $state -InterfaceGuid $entry.InterfaceGuid -RestoreStatus 'NOT_APPLIED' -ErrorCode 'DISABLE_NOT_VERIFIED'
                }
            } catch {
                Update-TMPCNetworkEntry -State $state -InterfaceGuid $entry.InterfaceGuid -RestoreStatus 'NOT_APPLIED' -ErrorCode 'DISABLE_FAILED'
            }
        }
        try { Write-TMPCNetworkState -State $state } catch { Write-NetworkLog ("Network state update failed after an adapter attempt ($($_.Exception.Message)).") 'ERROR' }
    }
    $disabled = @($state.Adapters | Where-Object { $_.DisabledByTmpc -eq $true }).Count
    $state.Phase = if ($disabled -eq @($state.Adapters).Count -and $disabled -gt 0) { 'DISABLED' } else { 'PARTIAL_DISABLE' }
    try { Write-TMPCNetworkState -State $state } catch { Write-NetworkLog 'Final network disable state could not be verified.' 'ERROR' }
    Write-NetworkLog ("Network adapters disabled by TMPC: {0}. Restoration is deferred until OOBE completes." -f $disabled) 'SUCCESS'
    return 0
}

function Register-TMPCNetworkRecoveryTask {
    try {
        $location = Test-TMPCNetworkRecoveryLocation -SourcePath $PSCommandPath -RecoveryDirectory $script:RecoveryDir -RecoveryScript $script:RecoveryScript
        if (-not $location.Safe) { throw "Recovery location is not trusted: $($location.Reason)." }
        $sourceHash = (Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256 -ErrorAction Stop).Hash
        Copy-Item -LiteralPath $PSCommandPath -Destination $script:RecoveryScript -Force -ErrorAction Stop
        $afterCopy = Test-TMPCNetworkRecoveryLocation -SourcePath $PSCommandPath -RecoveryDirectory $script:RecoveryDir -RecoveryScript $script:RecoveryScript
        if (-not $afterCopy.Safe) { throw "Recovery script destination is not trusted: $($afterCopy.Reason)." }
        $copyHash = (Get-FileHash -LiteralPath $script:RecoveryScript -Algorithm SHA256 -ErrorAction Stop).Hash
        if (-not [string]::Equals($sourceHash, $copyHash, [StringComparison]::OrdinalIgnoreCase)) { throw 'Recovery script copy verification failed.' }
        $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument ('-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File "{0}" -Mode Recover' -f $script:RecoveryScript)
        $trigger = New-ScheduledTaskTrigger -AtLogOn
        $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Minutes 10)
        $principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
        Register-ScheduledTask -TaskName $script:RecoveryTaskName -TaskPath $script:RecoveryTaskPath -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Force -ErrorAction Stop | Out-Null
        $registered = Get-ScheduledTask -TaskName $script:RecoveryTaskName -TaskPath $script:RecoveryTaskPath -ErrorAction Stop
        if (-not $registered) { throw 'Recovery task was not found after registration.' }
        $actionOk = @($registered.Actions | Where-Object {
            [string]::Equals([string]$_.Execute, 'powershell.exe', [StringComparison]::OrdinalIgnoreCase) -and
            ([string]$_.Arguments).Contains($script:RecoveryScript)
        }).Count -gt 0
        if (-not $actionOk) { throw 'Recovery task action does not reference the verified script copy.' }
        if (-not ([string]$registered.Principal.UserId -match '^(SYSTEM|S-1-5-18)$')) { throw 'Recovery task principal is not SYSTEM.' }
        Write-NetworkLog 'Registered the conditional logon recovery task for pending network adapters after verifying the script source, destination, ACL and hash.' 'WARNING'
        return $true
    } catch {
        Write-NetworkLog ("Recovery task could not be registered safely ($($_.Exception.Message)); use manual recovery instructions.") 'ERROR'
        # Never leave an older task pointing at an unverified copy.
        try {
            $unsafeTask = Get-ScheduledTask -TaskName $script:RecoveryTaskName -TaskPath $script:RecoveryTaskPath -ErrorAction SilentlyContinue
            if ($unsafeTask) { Unregister-ScheduledTask -TaskName $script:RecoveryTaskName -TaskPath $script:RecoveryTaskPath -Confirm:$false -ErrorAction Stop }
        } catch {
            Write-NetworkLog ("An existing unverified recovery task could not be removed ($($_.Exception.Message)); remove it manually.") 'WARNING'
        }
        return $false
    }
}

function Remove-TMPCNetworkRecoveryTask {
    try {
        $task = Get-ScheduledTask -TaskName $script:RecoveryTaskName -TaskPath $script:RecoveryTaskPath -ErrorAction SilentlyContinue
        if ($task) {
            Unregister-ScheduledTask -TaskName $script:RecoveryTaskName -TaskPath $script:RecoveryTaskPath -Confirm:$false -ErrorAction Stop
            $remaining = Get-ScheduledTask -TaskName $script:RecoveryTaskName -TaskPath $script:RecoveryTaskPath -ErrorAction SilentlyContinue
            if ($remaining) { throw 'Recovery task still exists after unregister.' }
        }
        if (Test-Path -LiteralPath $script:RecoveryScript) { Remove-Item -LiteralPath $script:RecoveryScript -Force -ErrorAction Stop }
        Write-NetworkLog 'Removed the network recovery task and its script copy.' 'INFO'
    } catch {
        Write-NetworkLog ("Network recovery cleanup did not complete ($($_.Exception.Message)); the task will retry or require manual removal.") 'WARNING'
    }
}

function Invoke-TMPCNetworkRestore {
    param([bool]$Recovery)
    $state = $null
    try { $state = Read-TMPCNetworkState } catch {
        Write-NetworkLog ("Network restore state is not usable ($($_.Exception.Message)); no adapter is enabled automatically.") 'ERROR'
        Write-NetworkLog 'Manual recovery: enable the required adapters in ncpa.cpl or Device Manager, then remove HKLM\SOFTWARE\TMPC-Windows-11-Optimization\NetworkRestore and the TMPC network recovery task.' 'WARNING'
        if ($Recovery) {
            try {
                $task = Get-ScheduledTask -TaskName $script:RecoveryTaskName -TaskPath $script:RecoveryTaskPath -ErrorAction SilentlyContinue
                if ($task) { Unregister-ScheduledTask -TaskName $script:RecoveryTaskName -TaskPath $script:RecoveryTaskPath -Confirm:$false -ErrorAction SilentlyContinue }
            } catch { }
        }
        return 1
    }
    if ($null -eq $state) {
        Write-NetworkLog 'No TMPC network restore state exists; nothing was changed.' 'INFO'
        if ($Recovery) { Remove-TMPCNetworkRecoveryTask }
        return 0
    }
    if ($state.Phase -in @('RESTORED', 'RESTORED_WITH_ABSENT')) {
        Write-NetworkLog ('Network restore was already completed (phase {0}).' -f $state.Phase) 'INFO'
        Remove-TMPCNetworkRecoveryTask
        return 0
    }
    $oobeComplete = Test-TMPCNetworkOobeComplete
    $adapters = @(Get-NetAdapter -ErrorAction Stop)
    $plan = Get-TMPCNetworkRestorePlan -PersistedAdapters @($state.Adapters) -CurrentAdapters $adapters -OobeComplete $oobeComplete
    if ($plan.Decision -eq 'DEFER') {
        Write-NetworkLog 'Network restore is deferred: OOBE is not complete yet.' 'WARNING'
        if ($Recovery) {
            $state | Add-Member -NotePropertyName 'RecoveryAttempts' -NotePropertyValue ([int]$state.RecoveryAttempts + 1) -Force
            try { Write-TMPCNetworkState -State $state } catch { }
            if ([int]$state.RecoveryAttempts -ge $script:MaxRecoveryAttempts) {
                Write-NetworkLog 'Network recovery retry limit reached before OOBE completed; manual recovery is required.' 'ERROR'
                Remove-TMPCNetworkRecoveryTask
            }
        } else {
            $null = Register-TMPCNetworkRecoveryTask
        }
        return 2
    }
    if ($plan.Decision -eq 'NO_ACTION') {
        $state.Phase = 'RESTORED'
        try { Write-TMPCNetworkState -State $state } catch { Write-NetworkLog 'Final network restore state could not be verified.' 'ERROR'; return 1 }
        Write-NetworkLog 'No TMPC-disabled adapter needs restoration.' 'SUCCESS'
        Remove-TMPCNetworkRecoveryTask
        return 0
    }
    foreach ($action in @($plan.Actions)) {
        switch ($action.Action) {
            'ENABLE' {
                $adapter = Get-TMPCNetworkAdapterByGuid -InterfaceGuid $action.InterfaceGuid
                if ($null -eq $adapter) {
                    Update-TMPCNetworkEntry -State $state -InterfaceGuid $action.InterfaceGuid -RestoreStatus 'ABSENT_NOT_RESTORED' -ErrorCode 'ADAPTER_NOT_FOUND'
                } else {
                    try {
                        Enable-NetAdapter -InputObject $adapter -Confirm:$false -ErrorAction Stop
                        $after = Get-TMPCNetworkAdapterByGuid -InterfaceGuid $action.InterfaceGuid
                        if ($null -ne $after -and [string]$after.Status -ne 'Disabled') {
                            Update-TMPCNetworkEntry -State $state -InterfaceGuid $action.InterfaceGuid -RestoreStatus 'RESTORED_VERIFIED'
                        } else {
                            Update-TMPCNetworkEntry -State $state -InterfaceGuid $action.InterfaceGuid -RestoreStatus 'RESTORE_FAILED' -ErrorCode 'ENABLE_NOT_VERIFIED'
                        }
                    } catch {
                        Update-TMPCNetworkEntry -State $state -InterfaceGuid $action.InterfaceGuid -RestoreStatus 'RESTORE_FAILED' -ErrorCode 'ENABLE_FAILED'
                    }
                }
            }
            'ALREADY_ENABLED' { Update-TMPCNetworkEntry -State $state -InterfaceGuid $action.InterfaceGuid -RestoreStatus 'ALREADY_ENABLED' }
            'ABSENT' { Update-TMPCNetworkEntry -State $state -InterfaceGuid $action.InterfaceGuid -RestoreStatus 'ABSENT_NOT_RESTORED' -ErrorCode 'ADAPTER_NOT_PRESENT' }
            default { Update-TMPCNetworkEntry -State $state -InterfaceGuid $action.InterfaceGuid -RestoreStatus 'RESTORE_FAILED' -ErrorCode 'INVALID_ACTION' }
        }
        try { Write-TMPCNetworkState -State $state } catch { Write-NetworkLog 'Network state update failed during restore.' 'ERROR' }
    }
    $pending = @($state.Adapters | Where-Object { ($_.DisabledByTmpc -eq $true -or $_.DisableAttempted -eq $true) -and $_.RestoreStatus -notin @('RESTORED_VERIFIED', 'ALREADY_ENABLED', 'ABSENT_NOT_RESTORED', 'NOT_APPLIED', 'NOT_DISABLED') })
    $absent = @($state.Adapters | Where-Object { $_.RestoreStatus -eq 'ABSENT_NOT_RESTORED' }).Count
    if ($pending.Count -eq 0) {
        $state.Phase = if ($absent -gt 0) { 'RESTORED_WITH_ABSENT' } else { 'RESTORED' }
        try { Write-TMPCNetworkState -State $state } catch { Write-NetworkLog 'Final network restore state could not be verified.' 'ERROR'; return 1 }
        if ($absent -gt 0) {
            Write-NetworkLog ("Network restore verified for present adapters; {0} adapter(s) were not present and require manual enablement after reconnection." -f $absent) 'WARNING'
        } else {
            Write-NetworkLog 'Network adapters disabled by TMPC were restored and verified.' 'SUCCESS'
        }
        Remove-TMPCNetworkRecoveryTask
        return 0
    }
    $state.Phase = 'RESTORE_PENDING'
    try { Write-TMPCNetworkState -State $state } catch { Write-NetworkLog 'Pending network restore state could not be verified.' 'ERROR' }
    Write-NetworkLog ("Network restore is pending for {0} adapter(s); manual recovery is also documented." -f $pending.Count) 'ERROR'
    if ($Recovery) {
        $state | Add-Member -NotePropertyName 'RecoveryAttempts' -NotePropertyValue ([int]$state.RecoveryAttempts + 1) -Force
        try { Write-TMPCNetworkState -State $state } catch { }
        if ([int]$state.RecoveryAttempts -ge $script:MaxRecoveryAttempts) {
            Write-NetworkLog 'Network recovery retry limit reached; the recovery task is removed and manual recovery is required.' 'ERROR'
            Remove-TMPCNetworkRecoveryTask
        }
    } else {
        $null = Register-TMPCNetworkRecoveryTask
    }
    return 1
}

$exitCode = 1
try {
    switch ($Mode) {
        'Disable' { $exitCode = Invoke-TMPCNetworkDisable }
        'Restore' { $exitCode = Invoke-TMPCNetworkRestore -Recovery $false }
        'Recover' { $exitCode = Invoke-TMPCNetworkRestore -Recovery $true }
    }
} catch {
    Write-NetworkLog ("Network guard failed ({0}, HRESULT 0x{1:X8})." -f $_.Exception.GetType().Name, $_.Exception.HResult) 'ERROR'
    $exitCode = 1
}
exit $exitCode

#Requires -Version 5.1
<#
.SYNOPSIS
    Enables .NET Framework 3.5 from matching local Windows media without
    downloads or reboots.
.DESCRIPTION
    The feature state is queried before any DISM call, the local sources\sxs
    directory is validated for the NetFx3 payload, DISM exit code is checked,
    and the final feature state is verified again. Outcomes distinguish an
    already enabled feature, an applicable local source, a pending reboot, an
    unavailable source and a real failure. The process always exits 0 so a
    missing optional payload cannot block Windows Setup; the explicit status
    file records the real outcome.
.NOTES
    Windows PowerShell 5.1. No Windows Update fallback and no automatic restart.
#>
[CmdletBinding()]
param(
    [switch]$AutoDetect
)

$ErrorActionPreference = 'Stop'
$script:LogPath = 'C:\ProgramData\TMPC-Windows-11-Optimization\Logs\NetFx3.log'
$script:StatusPath = 'C:\ProgramData\TMPC-Windows-11-Optimization\Logs\NetFx3Status.json'

function Write-NetFx3Log {
    param([string]$Message, [ValidateSet('INFO', 'SUCCESS', 'WARNING', 'ERROR')][string]$Level = 'INFO')
    try {
        $directory = Split-Path -Parent $script:LogPath
        if (-not (Test-Path -LiteralPath $directory)) { New-Item -Path $directory -ItemType Directory -Force -ErrorAction Stop | Out-Null }
        $line = '[{0}] [{1}] {2}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Level, $Message
        Add-Content -LiteralPath $script:LogPath -Value $line -Encoding UTF8 -ErrorAction Stop
    } catch { }
}

function Get-TMPCNetFx3SourceAssessment {
    param(
        [string]$Path,
        [bool]$DirectoryExists,
        [bool]$IsReparsePoint,
        [string[]]$FileNames
    )
    if (-not $DirectoryExists) { return [pscustomobject]@{ Usable = $false; Status = 'SOURCE_NOT_FOUND'; Detail = 'sources\sxs is not present.' } }
    if ($IsReparsePoint) { return [pscustomobject]@{ Usable = $false; Status = 'SOURCE_REPARSE'; Detail = 'sources\sxs is a reparse point.' } }
    $payload = @($FileNames | Where-Object { $_ -and [string]::Equals([System.IO.Path]::GetExtension($_), '.cab', [StringComparison]::OrdinalIgnoreCase) -and $_ -match '^microsoft-windows-netfx3-ondemand-package.*\.cab$' })
    if ($payload.Count -eq 0) {
        return [pscustomobject]@{ Usable = $false; Status = 'SOURCE_PAYLOAD_MISSING'; Detail = 'No NetFx3 on-demand package CAB was found.' }
    }
    return [pscustomobject]@{ Usable = $true; Status = 'SOURCE_READY'; Detail = ('Found {0} NetFx3 package file(s).' -f $payload.Count) }
}

function Get-TMPCNetFx3Decision {
    param(
        [string]$InitialState,
        [string]$SourceStatus,
        [int]$DismExitCode,
        [string]$FinalState,
        [bool]$RestartNeeded
    )
    if ($InitialState -eq 'Enabled') { return 'ALREADY_ENABLED' }
    if ($InitialState -eq 'EnablePending') { return 'PENDING_REBOOT' }
    if ($InitialState -eq 'DisablePending') { return 'NOT_APPLICABLE' }
    if ($InitialState -eq 'Unknown') { return 'UNKNOWN' }
    if ($SourceStatus -ne 'SOURCE_READY') { return 'SOURCE_UNAVAILABLE' }
    if ($FinalState -eq 'Enabled') { return 'APPLIED' }
    if ($RestartNeeded -or $DismExitCode -eq 3010 -or $FinalState -eq 'EnablePending') { return 'PENDING_REBOOT' }
    if ($DismExitCode -ne 0) { return 'FAILED' }
    return 'FAILED'
}

function Get-TMPCNetFx3FeatureState {
    try { return [string](Get-WindowsOptionalFeature -Online -FeatureName NetFx3 -ErrorAction Stop).State } catch { return 'Unknown' }
}

function Find-TMPCNetFx3Source {
    foreach ($drive in @(Get-PSDrive -PSProvider FileSystem -ErrorAction SilentlyContinue)) {
        $root = [string]$drive.Root
        if ([string]::IsNullOrWhiteSpace($root)) { continue }
        try {
            $driveInfo = New-Object System.IO.DriveInfo ($root)
            if ($driveInfo.DriveType -notin @('Fixed', 'Removable', 'CDRom')) { continue }
        } catch { continue }
        $source = Join-Path $root 'sources\sxs'
        if (-not (Test-Path -LiteralPath $source -PathType Container)) { continue }
        $isReparse = $false
        try {
            $item = Get-Item -LiteralPath $source -Force -ErrorAction Stop
            $isReparse = (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)
        } catch { $isReparse = $true }
        $names = @()
        try { $names = @(Get-ChildItem -LiteralPath $source -Filter '*.cab' -File -ErrorAction SilentlyContinue | ForEach-Object { $_.Name }) } catch { }
        $assessment = Get-TMPCNetFx3SourceAssessment -Path $source -DirectoryExists $true -IsReparsePoint $isReparse -FileNames $names
        if ($assessment.Usable) { return [pscustomobject]@{ Path = $source; Status = $assessment.Status; Detail = $assessment.Detail } }
    }
    return [pscustomobject]@{ Path = $null; Status = 'SOURCE_NOT_FOUND'; Detail = 'No local sources\sxs directory with the NetFx3 payload was found.' }
}

function Write-TMPCNetFx3Status {
    param([hashtable]$Status)
    try {
        $directory = Split-Path -Parent $script:StatusPath
        if (-not (Test-Path -LiteralPath $directory)) { New-Item -Path $directory -ItemType Directory -Force -ErrorAction Stop | Out-Null }
        $json = ([ordered]@{
            SchemaVersion = 1
            Feature       = 'NetFx3'
            Outcome       = [string]$Status.Outcome
            InitialState  = [string]$Status.InitialState
            FinalState    = [string]$Status.FinalState
            SourceStatus  = [string]$Status.SourceStatus
            SourcePath    = [string]$Status.SourcePath
            DismExitCode  = [int]$Status.DismExitCode
            RestartNeeded = [bool]$Status.RestartNeeded
            TimestampUtc  = (Get-Date).ToUniversalTime().ToString('o')
        }) | ConvertTo-Json -Depth 4
        [IO.File]::WriteAllText($script:StatusPath, $json, (New-Object System.Text.UTF8Encoding($false)))
        $persisted = [IO.File]::ReadAllText($script:StatusPath)
        if (-not [string]::Equals($persisted, $json, [StringComparison]::Ordinal)) { throw 'Status read-back mismatch.' }
    } catch {
        Write-NetFx3Log ("NetFx3 status could not be persisted ({0})." -f $_.Exception.GetType().Name) 'ERROR'
    }
}

$result = @{
    Outcome       = 'UNKNOWN'
    InitialState  = 'Unknown'
    FinalState    = 'Unknown'
    SourceStatus  = 'NOT_EVALUATED'
    SourcePath    = ''
    DismExitCode  = 0
    RestartNeeded = $false
}

try {
    $initialState = Get-TMPCNetFx3FeatureState
    $result.InitialState = $initialState
    Write-NetFx3Log ("NetFx3 initial feature state: {0}." -f $initialState) 'INFO'

    if ($initialState -eq 'Enabled') {
        $result.Outcome = 'ALREADY_ENABLED'
        $result.FinalState = 'Enabled'
        Write-NetFx3Log 'NetFx3 is already enabled; no installation was attempted.' 'SUCCESS'
    } elseif ($initialState -in @('EnablePending', 'DisablePending')) {
        $result.Outcome = if ($initialState -eq 'EnablePending') { 'PENDING_REBOOT' } else { 'NOT_APPLICABLE' }
        $result.FinalState = $initialState
        Write-NetFx3Log ("NetFx3 is in state {0}; no installation was attempted." -f $initialState) 'WARNING'
    } elseif ($initialState -eq 'Disabled') {
        $source = Find-TMPCNetFx3Source
        $result.SourceStatus = $source.Status
        $result.SourcePath = [string]$source.Path
        if (-not $source.Path) {
            $result.Outcome = 'SOURCE_UNAVAILABLE'
            $result.FinalState = $initialState
            Write-NetFx3Log ("A matching local sources\sxs payload was not found ({0}); no download was attempted." -f $source.Status) 'WARNING'
        } else {
            Write-NetFx3Log ("Using local NetFx3 source: {0}." -f $source.Path) 'INFO'
            $dismArgs = @('/Online', '/Enable-Feature', '/FeatureName:NetFx3', '/All', '/LimitAccess', ('/Source:' + $source.Path), '/NoRestart')
            & dism.exe @dismArgs 2>&1 | Out-Null
            $dismCode = if ($null -eq $LASTEXITCODE) { -1 } else { [int]$LASTEXITCODE }
            $result.DismExitCode = $dismCode
            $finalState = Get-TMPCNetFx3FeatureState
            $result.FinalState = $finalState
            $restartNeeded = ($dismCode -eq 3010 -or $finalState -eq 'EnablePending')
            $result.RestartNeeded = $restartNeeded
            $result.Outcome = Get-TMPCNetFx3Decision -InitialState $initialState -SourceStatus 'SOURCE_READY' -DismExitCode $dismCode -FinalState $finalState -RestartNeeded $restartNeeded
            $level = if ($result.Outcome -in @('APPLIED', 'PENDING_REBOOT')) { 'SUCCESS' } else { 'WARNING' }
            Write-NetFx3Log ("NetFx3 DISM exit code {0}; final state {1}; outcome {2}." -f $dismCode, $finalState, $result.Outcome) $level
        }
    } else {
        $result.Outcome = 'UNKNOWN'
        Write-NetFx3Log 'NetFx3 feature state could not be determined; no installation was attempted.' 'ERROR'
    }
} catch {
    $result.Outcome = 'FAILED'
    Write-NetFx3Log ("NetFx3 local-source operation failed ({0}, HRESULT 0x{1:X8})." -f $_.Exception.GetType().Name, $_.Exception.HResult) 'ERROR'
}

Write-TMPCNetFx3Status -Status $result
exit 0
